# canary.py
# Honey directories + believable bait (canary) files banata hai.
# Canary file = fake sensitive file. Legit program isko kabhi nahi chhuta,
# toh jo bhi isko modify kare wo suspicious hai.

import os
import random

from . import config


def _bait_content(name: str) -> bytes:
    """
    Canary file ke andar ka content — human-readable, LOW entropy.
    Taaki jab ransomware isko encrypt kare toh entropy spike clearly dikhe.
    """
    text = (
        "# CONFIDENTIAL - do not share\n"
        "# generated by sentinel-canary\n"
        "service,username,password\n"
        "email,admin,Winter2024!\n"
        "vpn,kunal,SecurePass123\n"
        "bank,savings,Hunter2!hunter\n"
    )
    return text.encode("utf-8")


def ensure_honey_dirs(seed: int = config.SIM_SEED) -> list:
    """
    HONEY_DIR ke andar subdirectories + canary files banao.
    Return: bani hui canary files ka path list.
    Pehle se ho toh waise hi rehne do (idempotent).
    """
    created = []
    for sub in config.HONEY_SUBDIRS:
        d = os.path.join(config.HONEY_DIR, sub)
        os.makedirs(d, exist_ok=True)
        for fname in config.CANARY_FILES:
            path = os.path.join(d, fname)
            if not os.path.exists(path):
                with open(path, "wb") as f:
                    f.write(_bait_content(fname))
                created.append(path)
    return created


def is_canary(path: str) -> bool:
    """Check karo path kisi canary file ka hai ya nahi."""
    if not path:
        return False
    ap = os.path.abspath(path)
    return ap.startswith(os.path.abspath(config.HONEY_DIR))


def snapshot_honey_dir() -> str:
    """
    Honey dir ka backup (snapshot) lo — rollback ke liye.
    Simple tarika: files ko SNAP_DIR me timestamp ke saath copy.
    """
    import shutil, time
    os.makedirs(config.SNAP_DIR, exist_ok=True)
    ts = time.strftime("%Y%m%d_%H%M%S")
    dst = os.path.join(config.SNAP_DIR, f"honey_{ts}")
    if os.path.isdir(config.HONEY_DIR):
        shutil.copytree(config.HONEY_DIR, dst)
    return dst


def _force_writeable(func, path, _exc):
    """rmtree ke liye error-handler — read-only/locked file ko writable bana ke delete."""
    try:
        os.chmod(path, 0o666)
        func(path)
    except Exception:
        pass


def restore_latest_snapshot() -> str:
    """Sabse latest snapshot se honey dir restore karo."""
    import shutil, stat
    snaps = sorted(
        os.path.join(config.SNAP_DIR, s)
        for s in os.listdir(config.SNAP_DIR)
        if s.startswith("honey_")
    )
    if not snaps:
        return ""
    latest = snaps[-1]
    if os.path.isdir(config.HONEY_DIR):
        # Pehle pura honey dir saaf karo (attack ke leftovers incl. .locked),
        # phir snapshot se restore — taaki sirf clean canary files wapas aaye.
        for root, dirs, files in os.walk(config.HONEY_DIR, topdown=False):
            for f in files:
                p = os.path.join(root, f)
                try:
                    os.chmod(p, 0o666)
                except Exception:
                    pass
                removed = False
                try:
                    os.remove(p); removed = True
                except Exception:
                    pass
                if not removed:
                    # kuch mounts/filesystems pe remove lock hota hai —
                    # rename-to-trash try karo taaki file restore path se hat jaye.
                    try:
                        os.rename(p, p + ".trash")
                    except Exception:
                        pass
            for d in dirs:
                try:
                    os.rmdir(os.path.join(root, d))
                except Exception:
                    pass
    shutil.copytree(latest, config.HONEY_DIR, dirs_exist_ok=True)
    return latest
